//! Embedded dashboard assets admitted to the shared HTTP delivery authority.

// The single-app dashboard (dashboard/app-dist) embedded via the manifest
// generated by build.rs. The delivery crate derives MIME, cache, and exact
// content validators so this manifest carries bytes and paths only.
mod app_manifest {
    include!(concat!(env!("OUT_DIR"), "/dashboard_app_assets.rs"));
}
use app_manifest::APP_ASSETS;

pub(crate) fn router() -> Result<axum::Router, tracedecay_api::delivery::EmbeddedAssetError> {
    tracedecay_api::delivery::embedded_asset_router(
        APP_ASSETS
            .iter()
            .map(|asset| tracedecay_api::delivery::EmbeddedAsset::new(asset.path, asset.contents)),
        "index.html",
    )
}
